import heapq


def _build_quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for chosen in combinations([job for job in jobs if job["id"] not in blocked], k):
            ids = tuple(sorted(job["id"] for job in chosen))
            if not mandatory.issubset(ids):
                continue

            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            ends = []
            valid = True
            for job in sorted(chosen, key=lambda row: (row["start"], row["end"])):
                while ends and ends[0] <= job["start"]:
                    heapq.heappop(ends)
                heapq.heappush(ends, job["end"])
                if len(ends) > capacity:
                    valid = False
                    break
            if not valid:
                continue

            value = sum(job["value"] for job in chosen)
            better_tie = (best_ids is None or
                          (ids > best_ids if tie == "largest" else ids < best_ids))
            if best_value is None or value > best_value or (value == best_value and better_tie):
                best_value, best_ids = value, ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            price = event["price"]
            raw = price * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(raw * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        domains = [[None] + [row["version"] for row in packages[name]] for name in names]
        best_key = None
        best_versions = None

        for choices in product(*domains):
            selected = dict(zip(names, choices))
            if any(name in pins and selected[name] is not None and selected[name] != pins[name]
                   for name in names):
                continue
            rows = {}
            valid = True
            for name, version in selected.items():
                if version is None:
                    continue
                if version in blocked.get(name, []):
                    valid = False
                    break
                rows[name] = next(row for row in packages[name] if row["version"] == version)
            if not valid:
                continue

            for name, (low, high) in roots.items():
                version = selected[name]
                if version is None or not low <= version <= high:
                    valid = False
                    break
            if not valid:
                continue

            edges = {}
            for name, row in rows.items():
                deps = [dep for dep in row.get("deps", [])
                        if not dep.get("feature") or dep["feature"] in features]
                edges[name] = []
                for dep in deps:
                    target = selected[dep["name"]]
                    if target is None or not dep["min"] <= target <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(dep["name"])
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(rows):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(dep) for dep in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in rows):
                continue

            order = sorted(names, reverse=True)
            vector = tuple(selected[name] if selected[name] is not None else -1 for name in order)
            if best_key is None or vector < best_key:
                best_key = vector
                best_versions = {name: selected[name] for name in names if selected[name] is not None}

        if best_key is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        full_mask = (1 << len(required)) - 1
        required_bits = {}
        for index, node in enumerate(required):
            required_bits[node] = required_bits.get(node, 0) | (1 << index)

        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = required_bits.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        distances = {initial: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]

        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full_mask:
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], remaining)]
                if remaining:
                    choices.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
                next_mask = mask | required_bits.get(edge["v"], 0)
                for duration, next_remaining in choices:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_remaining)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, edge["v"], next_mask, next_remaining))

        return {"arrival": None}
    return solve


